theorem classical_transcript_product_law {β : Type}
    (T : OutTree (Fin r × κ) β) (τ : ClassicalTranscript r κ)
    (μ : Fin r → BitInput κ → ℝ)
    (hm : 0 < ∑ V : Fin r → BitInput κ,
      if classicalPrefix T τ V then ∏ h, μ h (V h) else 0)
    (U : Fin r → BitInput κ) :
    (if classicalPrefix T τ U then ∏ h, μ h (U h) else 0) /
        (∑ V : Fin r → BitInput κ,
          if classicalPrefix T τ V then ∏ h, μ h (V h) else 0) =
      ∏ h, classicalLaw (classicalTranscriptWeight μ τ h) (U h)

theorem quantumList_coupling (ha : UnitValued a) (hv : ∀ c, 0 ≤ v c ∧ v c ≤ 1)
    (hf : ∀ L, 0 ≤ f L ∧ f L ≤ 1) (hz : ∀ L, total (weight a L) = 0 → f L = 1) {s : Col}
    {ε : ℝ} (hε0 : 0 ≤ ε) (hε1 : ε ≤ 1) (hd : Dominant a ε s) (hvs : v s = 1) {T₀ : ℕ}
    (hT : (T₀ : ℝ) * ε < 1 / 2) (hfail : ∀ L : List Col, L.length ≤ T₀ → s ∉ L → f L ≤ ε)
    (T : ℕ) (L : List Col) (hL : L.length + T ≤ T₀) :
    1 - missFrom a s T L - T * ε ≤ tval a v f T L
